/**  場所の状態。 */
export type LocationStatusDto = "new" | "existingLibrary" | "occupied";

/**  ⌃⌥⌘C（ログイン用の Chrome を見ながら撮る）の結果（イベント `capture://login-shot`。ADR-112）。 */
